    ('UBOT_LIFE_01', 'Ubot 라이프 뮤직 15GB', '월 데이터 15GB, 소진 후 최대 1Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 15GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 뮤직패스 1개 포함.', 'LTE', 'GENERAL', 22900, 15000, FALSE, 1000, NULL, TRUE, NULL, TRUE, 15000, NULL, NULL, 'ACTIVE'),
    ('UBOT_LIFE_02', 'Ubot 라이프 비디오 100GB', '월 데이터 100GB, 소진 후 최대 5Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 20GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 비디오패스 1개 포함.', 'LTE', 'GENERAL', 42900, 100000, FALSE, 5000, NULL, TRUE, NULL, TRUE, 20000, NULL, NULL, 'ACTIVE'),
    ('UBOT_LIFE_03', 'Ubot 라이프 커피 10GB', '월 데이터 10GB, 소진 후 최대 1Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 10GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 카페 월 5,000포인트. 발급 월 말 만료·현금 환급 불가.', 'LTE', 'GENERAL', 21900, 10000, FALSE, 1000, NULL, TRUE, NULL, TRUE, 10000, NULL, NULL, 'ACTIVE'),
    ('UBOT_LIFE_04', 'Ubot 라이프 교통 20GB', '월 데이터 20GB, 소진 후 최대 1Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 20GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 교통지갑 월 5,000포인트. 발급 월 말 만료·현금 환급 불가.', 'LTE', 'GENERAL', 25900, 20000, FALSE, 1000, NULL, TRUE, NULL, TRUE, 20000, NULL, NULL, 'ACTIVE'),
    ('UBOT_LIFE_05', 'Ubot 라이프 쇼핑 30GB', '월 데이터 30GB, 소진 후 최대 1Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 20GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 스토어 월 5,000포인트. 발급 월 말 만료·현금 환급 불가.', 'LTE', 'GENERAL', 29900, 30000, FALSE, 1000, NULL, TRUE, NULL, TRUE, 20000, NULL, NULL, 'ACTIVE'),
    ('UBOT_LIFE_06', 'Ubot 라이프 보안 10GB', '월 데이터 10GB, 소진 후 최대 1Mbps로 계속 이용. 국내 일반 음성 기본제공, 국내 문자 기본제공. 테더링 월 10GB이며 유한 데이터 상품은 기본 제공량에서 함께 차감. 표시 월정액은 부가세 포함, 기간 한정 할인 없이 유지. 음성·문자 기본제공은 국제전화·영상통화·유료 특수번호를 제외. 테더링 한도 소진 후 테더링 차단. 가상 Ubot 피싱가드 포함. 금융 손해 보험·보상은 제공하지 않음.', 'LTE', 'GENERAL', 20900, 10000, FALSE, 1000, NULL, TRUE, NULL, TRUE, 10000, NULL, NULL, 'ACTIVE')
