-- [3] 사용자·회선·이력 임시 자료 및 충돌 검사
-- 새 영구 테이블·시퀀스 초기화·기존 데이터 수정/삭제 없음. ID는 DB가 생성한다.
-- 사용자/상품 ID 하드코딩 대신 이메일·상품 코드·가상 SIM 식별자로 연결한다.
-- 재실행 시 이미 있는 가상 사용자는 그 사용자의 전체 연관 자료와 함께 건너뛴다.
-- 기존 가상 사용자 자료를 수정·삭제한 뒤 재실행해도 덮어쓰거나 자동 복구하지 않는다.
-- 기존 이메일이 다른 계정이거나 삭제된 계정이면 전체 작업을 중단한다.
-- 각 계정 BCrypt cost 10 / 개별 무작위 salt. 모두 USER, 관리자 권한 없음.
-- 실재 고객 자료 아님. 이름은 '가상 ' 접두사, 전화 010-0000/0001, SIM은 UBOT_DEMO 식별자.
-- 만 나이와 요금제 대상 일치. 약정 없는 요금제에는 NONE 대신 약정 행을 만들지 않는다.
-- 사용량: 2026-07~10, 과거 해지 회선은 2025-10~12. 10월은 10/10까지의 미확정 사용량.
-- 청구: 완료된 월만. 가상 요율: 유한 음성 초과 18원/분, 문자 초과 22원/건.
-- extra_fee는 초과 통화/문자 + 단말 월 할부금. 미납 단말 할부 사례는 만들지 않았다.
-- 신규 가입월 기본료·정액 부가료는 일할 계산, 추가 데이터팩은 고정 제공량.
-- 선택약정은 가상 정책 25%, 결합 중복할인 합계는 기본료 이내. 결합 전체액은 대표 회선만 적용.
-- 결합 구성원 그룹 식별 컬럼은 현 스키마에 없어 그룹별 구성표는 ubot-user-data/ubot-users-300.preview.json에 보관한다(실행에는 불필요).
-- 정지 회선은 2026-10-05부터 정지한 예시. 10월 청구를 만들지 않아 정지 요금 규칙은 가정하지 않는다.

CREATE TEMP TABLE _seed_users (
  user_no INTEGER,
  email VARCHAR(255),
  password_hash VARCHAR(255),
  name VARCHAR(100),
  birth_date DATE,
  gender VARCHAR(20),
  residence_area VARCHAR(200),
  role VARCHAR(20),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_subscriptions (
  sub_key VARCHAR(100),
  user_no INTEGER,
  plan_code VARCHAR(100),
  phone_number VARCHAR(30),
  status VARCHAR(20),
  activated_at TIMESTAMP,
  terminated_at TIMESTAMP,
  sim_type VARCHAR(20),
  sim_identifier VARCHAR(100),
  sim_status VARCHAR(20),
  sim_activated_at TIMESTAMP,
  sim_deactivated_at TIMESTAMP,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_usage_records (
  sub_key VARCHAR(100),
  billing_month DATE,
  data_used_mb BIGINT,
  voice_used_minutes INTEGER,
  sms_used_count INTEGER,
  allowance_snapshot JSONB,
  aggregated_through_date DATE,
  finalized_at TIMESTAMP,
  full_month_active BOOLEAN,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_billing_records (
  sub_key VARCHAR(100),
  billing_month DATE,
  base_fee INTEGER,
  addon_fee INTEGER,
  roaming_fee INTEGER,
  extra_fee INTEGER,
  discount_amount INTEGER,
  total_amount INTEGER,
  due_date DATE,
  payment_status VARCHAR(20),
  paid_amount INTEGER,
  payment_method VARCHAR(20),
  paid_at TIMESTAMP,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_subscription_contracts (
  sub_key VARCHAR(100),
  contract_type VARCHAR(30),
  started_at DATE,
  expires_at DATE,
  discount_amount INTEGER,
  status VARCHAR(20),
  canceled_at TIMESTAMP,
  device_name VARCHAR(150),
  device_total_amount INTEGER,
  installment_months INTEGER,
  paid_installment_months INTEGER,
  monthly_installment_amount INTEGER,
  remaining_installment_amount INTEGER,
  installment_started_at DATE,
  installment_expires_at DATE,
  installment_status VARCHAR(20),
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_subscription_bundles (
  sub_key VARCHAR(100),
  bundle_code VARCHAR(100),
  joined_at TIMESTAMP,
  ended_at TIMESTAMP,
  status VARCHAR(20),
  product_name_snapshot VARCHAR(150),
  applied_discount_amount INTEGER,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_subscription_addons (
  sub_key VARCHAR(100),
  addon_code VARCHAR(100),
  subscribed_at TIMESTAMP,
  canceled_at TIMESTAMP,
  status VARCHAR(20),
  service_name_snapshot VARCHAR(150),
  monthly_fee_snapshot INTEGER,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_subscription_roamings (
  sub_key VARCHAR(100),
  roaming_code VARCHAR(100),
  start_date DATE,
  end_date DATE,
  status VARCHAR(20),
  product_name_snapshot VARCHAR(150),
  daily_fee_snapshot INTEGER,
  data_amount_mb_snapshot BIGINT,
  canceled_at TIMESTAMP,
  created_at TIMESTAMP,
  updated_at TIMESTAMP
) ON COMMIT DROP;

CREATE TEMP TABLE _seed_expected_products (kind TEXT, code TEXT, expected JSONB) ON COMMIT DROP;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM users u JOIN _seed_users s ON s.email=u.email
             WHERE u.deleted_at IS NOT NULL OR u.role <> 'USER'
                OR u.password_hash <> s.password_hash OR u.name NOT LIKE '가상 %') THEN
    RAISE EXCEPTION 'Demo email collision or modified credentials; existing rows were not changed.';
  END IF;
  IF EXISTS (SELECT 1 FROM _seed_users s WHERE NOT EXISTS (SELECT 1 FROM users u WHERE u.email=s.email))
     AND EXISTS (
       SELECT 1 FROM _seed_expected_products e LEFT JOIN (
         SELECT 'plans' AS kind, plan_code AS code, to_jsonb(p) AS actual FROM plans p
         UNION ALL SELECT 'addon_services', code, to_jsonb(p) FROM addon_services p
         UNION ALL SELECT 'bundle_products', code, to_jsonb(p) FROM bundle_products p
         UNION ALL SELECT 'roaming_products', code, to_jsonb(p) FROM roaming_products p
       ) a ON a.kind=e.kind AND a.code=e.code
       WHERE a.code IS NULL OR NOT (a.actual @> e.expected)) THEN
    RAISE EXCEPTION 'Missing or changed Ubot product; apply/review the matching product seed first.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM _seed_subscriptions s JOIN _seed_users su ON su.user_no=s.user_no
    JOIN subscriptions x ON x.sim_identifier=s.sim_identifier
      OR (x.phone_number=s.phone_number AND x.status <> 'TERMINATED' AND s.status <> 'TERMINATED')
    JOIN users u ON u.user_id=x.user_id
    WHERE u.email <> su.email OR x.sim_identifier IS DISTINCT FROM s.sim_identifier) THEN
    RAISE EXCEPTION 'Demo phone/SIM collision; no existing subscription was changed.';
  END IF;
END $$;

-- [4] 사용자 저장 및 실제 user_id 매핑
CREATE TEMP TABLE _seed_user_map ON COMMIT DROP AS
WITH inserted AS (
  SELECT email,password_hash,name,birth_date,gender,residence_area,role,created_at,updated_at FROM _seed_users
  ON CONFLICT (email) WHERE deleted_at IS NULL DO NOTHING
  RETURNING user_id,email
)
SELECT s.user_no,i.user_id FROM inserted i JOIN _seed_users s ON s.email=i.email;

-- [5] 회선 저장 및 실제 subscription_id 매핑
CREATE TEMP TABLE _seed_sub_map ON COMMIT DROP AS
WITH inserted AS (
    sim_type,sim_identifier,sim_status,sim_activated_at,sim_deactivated_at,created_at,updated_at)
  SELECT u.user_id,p.plan_id,s.phone_number,s.status,s.activated_at,s.terminated_at,
    s.sim_type,s.sim_identifier,s.sim_status,s.sim_activated_at,s.sim_deactivated_at,s.created_at,s.updated_at
  FROM _seed_subscriptions s JOIN _seed_user_map u ON u.user_no=s.user_no
  JOIN plans p ON p.plan_code=s.plan_code
  RETURNING subscription_id,sim_identifier
)
SELECT s.sub_key,i.subscription_id FROM inserted i JOIN _seed_subscriptions s ON s.sim_identifier=i.sim_identifier;

-- [6] 사용량·청구·약정·결합·부가서비스·로밍 이력 저장
SELECT m.subscription_id,s.billing_month,s.data_used_mb,s.voice_used_minutes,s.sms_used_count,s.allowance_snapshot,s.aggregated_through_date,s.finalized_at,s.full_month_active,s.updated_at
FROM _seed_usage_records s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
;

SELECT m.subscription_id,s.billing_month,s.base_fee,s.addon_fee,s.roaming_fee,s.extra_fee,s.discount_amount,s.total_amount,s.due_date,s.payment_status,s.paid_amount,s.payment_method,s.paid_at,s.created_at,s.updated_at
FROM _seed_billing_records s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
;

SELECT m.subscription_id,s.contract_type,s.started_at,s.expires_at,s.discount_amount,s.status,s.canceled_at,s.device_name,s.device_total_amount,s.installment_months,s.paid_installment_months,s.monthly_installment_amount,s.remaining_installment_amount,s.installment_started_at,s.installment_expires_at,s.installment_status,s.created_at,s.updated_at
FROM _seed_subscription_contracts s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
;

SELECT m.subscription_id,p.bundle_product_id,s.joined_at,s.ended_at,s.status,s.product_name_snapshot,s.applied_discount_amount,s.created_at,s.updated_at
FROM _seed_subscription_bundles s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
JOIN bundle_products p ON p.code=s.bundle_code;

SELECT m.subscription_id,p.addon_service_id,s.subscribed_at,s.canceled_at,s.status,s.service_name_snapshot,s.monthly_fee_snapshot,s.created_at,s.updated_at
FROM _seed_subscription_addons s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
JOIN addon_services p ON p.code=s.addon_code;

SELECT m.subscription_id,p.roaming_product_id,s.start_date,s.end_date,s.status,s.product_name_snapshot,s.daily_fee_snapshot,s.data_amount_mb_snapshot,s.canceled_at,s.created_at,s.updated_at
FROM _seed_subscription_roamings s JOIN _seed_sub_map m ON m.sub_key=s.sub_key
JOIN roaming_products p ON p.code=s.roaming_code;

-- [7] 연관 행 수 확인 후 일괄 커밋. 조회 누락 시 전체 롤백.
DO $$
DECLARE t TEXT; actual_count BIGINT; expected_count BIGINT;
BEGIN
  SELECT count(*) INTO expected_count FROM _seed_subscriptions s JOIN _seed_user_map m ON m.user_no=s.user_no;
  IF (SELECT count(*) FROM _seed_sub_map) <> expected_count THEN
    RAISE EXCEPTION 'Subscription count mismatch';
  END IF;
  FOREACH t IN ARRAY ARRAY['usage_records','billing_records','subscription_contracts',
                          'subscription_bundles','subscription_addons','subscription_roamings'] LOOP
    EXECUTE format('SELECT count(*) FROM %I s JOIN _seed_sub_map m ON m.sub_key=s.sub_key', '_seed_'||t)
      INTO expected_count;
    EXECUTE format('SELECT count(*) FROM %I r JOIN _seed_sub_map m ON m.subscription_id=r.subscription_id', t)
      INTO actual_count;
    IF actual_count <> expected_count THEN RAISE EXCEPTION '% count mismatch',t; END IF;
  END LOOP;
END $$;
SELECT 'new_users' AS item,count(*) AS inserted_count FROM _seed_user_map
UNION ALL SELECT 'new_subscriptions',count(*) FROM _seed_sub_map;
COMMIT;
